<header class="page-header"><div><h1><?= e(t('Quick Capture')) ?></h1><p><?= e(t('Capture an idea anywhere in LifeOS with Ctrl Shift Space. Review the parsed fields before creating a task.')) ?></p></div><a href="/planner"><?= e(t('Planner')) ?></a></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<section class="card"><h2><?= e(t('Capture inbox')) ?></h2><p class="muted" role="status"><?= count($captures) ?> <?= e(t('pending captures')) ?></p><form class="stack" method="post" action="/planner/capture"><?= csrf_field() ?><label><?= e(t('Capture an idea')) ?><textarea id="capture-text" aria-describedby="capture-help" name="text" maxlength="2000" required placeholder="<?= e(t('call amma tomorrow 5pm !high ~30m')) ?>"></textarea></label><p class="muted" id="capture-help"><?= e(t('Dates: today / tomorrow / හෙට / நாளை / YYYY-MM-DD. Time: 5pm or 17:00. Priority: !high / !normal / !low. Duration: ~30m.')) ?></p><button><?= e(t('Preview')) ?></button></form></section>
<?php if(module_enabled('Intelligence')): ?><details class="card"><summary><?= e(t('Describe it in your own words')) ?></summary><form class="stack" method="post" action="/intelligence/understand"><?= csrf_field() ?><label><?= e(t('What would you like to do?')) ?><textarea name="text" maxlength="20000" rows="4" required></textarea></label><label class="checkbox-label"><input type="checkbox" name="share_tasks" value="yes"><span><?= e(t('Include open task titles and due dates to suggest task moves.')) ?></span></label><p class="footnote"><?= e(t('Your typed text is processed online. Existing records are included only when you select the sharing option.')) ?></p><button><?= e(t('Prepare suggestions')) ?></button></form></details><?php endif; ?>
<?php foreach ($captures as $capture): $draft=json_decode($capture['draft'],true,512,JSON_THROW_ON_ERROR); ?>
